mapper.select:
select v.* from (SELECT cc.contract_number, cc.contract_status, pp.employee_id,pp.manufacturer_id,pp.tenant_id, pp.sign_status, ( SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'SIGN_STATUS' AND v.code_id = b.code_id AND v. VALUE = nvl ( pp.sign_status, 'NEW' ) ) sign_status_n, ( SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'CON.CONTRACT_STATUS' AND v.code_id = b.code_id AND v. VALUE = cc.contract_status ) contract_status_n ,( SELECT fe.NAME FROM fnd_employee fe WHERE fe.employee_id = pp.employee_id ) employee_id_n, ( SELECT hb.bp_name FROM hls_bp_master hb WHERE hb.bp_id = pp.manufacturer_id ) manufacturer_id_n, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = pp.tenant_id ) bp_id_tenant_n,
(SELECT fou.UNIT_NAME FROM fnd_org_unit fou,FND_EMPLOYEE_ASSIGNS fea WHERE fea.employee_id=pp.employee_id and fou.UNIT_ID=fea.unit_id
AND fou.ENABLED_FLAG = 'Y') lease_organization_n,ccli.full_name, ccli.serial_number asset_number,clii.insurance_number, clii.insurance_type, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'NEW_INSURANCE_TYPE' AND code_value = clii.insurance_type ) AS insurance_type_n, clii.insurance_date_from, clii.insurance_date_to, clii.insurance_amount FROM con_LEASE_ITEM_INSURANCE clii left join con_contract_lease_item ccli on clii.con_lease_item_id =ccli.contract_lease_item_id LEFT JOIN con_contract cc ON ccli.contract_id = cc.contract_id LEFT JOIN prj_project pp ON pp.project_id = cc.project_id) v
and v.contract_number like concat('%',concat(#{contractNumber},'%'))
and v.lease_organization_n like concat('%',concat(#{leaseOrganizationN},'%'))
and v.bp_id_tenant_n like concat('%',concat(#{bpIdTenantN},'%'))
and v.employee_id = #{employeeId}
and v.manufacturer_id = #{manufacturerId}
and v.insurance_number like concat('%',concat(#{insuranceNumber},'%'))
and v.insurance_type = #{insuranceType}
and v.sign_status = #{signStatus}
and v.contract_status = #{contractStatus}
and v.insurance_date_from >= to_date(#{insuranceDateFrom},'yyyy-MM-dd')
and v.insurance_date_to <= to_date(#{insuranceDateTo},'yyyy-MM-dd')
